#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/..";FIXTURE="experiments/lab-visual-foundation-001.json";TMP_ROOT="$(mktemp -d)";trap 'rm -rf "$TMP_ROOT"' EXIT
go test ./...;go vet ./...;OUT1="$(go run ./cmd/ohf-lab experiment run "$FIXTURE")";echo "$OUT1";RUN_ID="$(printf '%s\n' "$OUT1"|awk -F= '/^RUN_ID=/{print $2}')";RUN_DIR="$(printf '%s\n' "$OUT1"|awk -F= '/^RUN_DIR=/{print $2}')";PNG_SHA="$(printf '%s\n' "$OUT1"|awk -F= '/^PNG_SHA256=/{print $2}')";PIXEL_SHA="$(printf '%s\n' "$OUT1"|awk -F= '/^PIXEL_SHA256=/{print $2}')";PNG_BYTES="$(printf '%s\n' "$OUT1"|awk -F= '/^PNG_BYTES=/{print $2}')";[ "$PNG_BYTES" -le 500000 ];cp -a "$RUN_DIR" "$TMP_ROOT/first";go run ./cmd/ohf-lab run verify "$RUN_ID";OUT2="$(go run ./cmd/ohf-lab experiment run "$FIXTURE")";[ "$RUN_ID" = "$(printf '%s\n' "$OUT2"|awk -F= '/^RUN_ID=/{print $2}')" ];[ "$PNG_SHA" = "$(printf '%s\n' "$OUT2"|awk -F= '/^PNG_SHA256=/{print $2}')" ];[ "$PIXEL_SHA" = "$(printf '%s\n' "$OUT2"|awk -F= '/^PIXEL_SHA256=/{print $2}')" ];diff -ru "$TMP_ROOT/first" "$RUN_DIR";echo VISUAL_BYTE_FOR_BYTE_REPLAY=PASS;echo CARRIER_SIZE_PASS=$PNG_BYTES
